actions.script:
const L = (text) => ec.l10n.localize(text)
const fmt = (value) => value == null ? '' : ec.l10n.format(Math.round(Number(String(value)) * 100) / 100, '#,##0.##')
const options = ec.service.sync().name('ironstone.projects.ReportServices.get#ReportOptions').call() || {}
ec.message.clearErrors()
projectOptions = Array.from(options.projectOptions || [])
personOptions = Array.from(options.personOptions || [])
clientOptions = Array.from(options.clientOptions || [])
workTypeOptions = Array.from(options.workTypeOptions || [])
criterionOptions = [['project', 'Project'], ['topItem', 'Top-level item'], ['parent', 'Parent item'], ['workItem', 'Work item'], ['person', 'Person'],
    ['workType', 'Work type'], ['client', 'Client'], ['billable', 'Billable']].map(([value, label]) => ({value: value, label: L(label)}))
const criterionLabel = {}
for (const one of criterionOptions) criterionLabel[one.value] = one.label
if (!criterion1 && !criterion2 && !criterion3) criterion1 = 'project'
const criteria = [criterion1, criterion2, criterion3].filter((one) => one && criterionLabel[one])
if (!period) period = 'week'
// an item filter by its key, as typed
const itemId = workEffortId ? String(workEffortId).trim().toUpperCase() : null
const out = ec.service.sync().name('mantle.work.ProjectReportServices.get#TimeReport').parameters({fromDate: fromDate || null, thruDate: thruDate || null,
    period: period, criteria: criteria, rootWorkEffortId: rootWorkEffortId || null, workEffortId: itemId, partyId: partyId || null,
    workTypeEnumId: workTypeEnumId || null, clientPartyId: clientPartyId || null, billable: billable || null}).call() || {}
ec.message.clearErrors()
fromDate = out.fromDay; thruDate = out.thruDay
const crits = Array.from(out.criteriaList || criteria)
critTitles = [0, 1, 2].map((i) => crits[i] ? criterionLabel[crits[i]] : '')
critCount = crits.length
amountsShown = !!out.amountsShown
const totals = out.totals || {}
const currency = totals.currencyUomId || 'USD'
const money = (value) => value == null ? '' : ec.l10n.formatCurrency(value, currency)
const periods = Array.from(out.periodList || [])
// a column per period, up to fourteen (form-list fields are fixed; the chart and CSV say the same)
maxPeriods = 14
periodCount = Math.min(periods.length, maxPeriods)
periodsCut = periods.length > maxPeriods
periodTitles = []
for (let i = 0; i < maxPeriods; i++) periodTitles.push(i < periods.length ? periods[i].label : '')
const rowOf = (values, periodHours, row, isTotal) => {
    const one = {isTotal: isTotal, hoursText: fmt(row.hours), billableText: fmt(row.billableHours), nonBillableText: fmt(row.nonBillableHours),
        amountText: amountsShown && row.amount != null ? money(row.amount) : ''}
    for (let i = 0; i < 3; i++) one['crit' + i] = values[i] ? values[i].label : ''
    for (let i = 0; i < maxPeriods; i++) one['p' + i] = i < periodHours.length ? (periodHours[i] ? fmt(periodHours[i]) : '') : ''
    return one
}
timeRows = Array.from(out.rowList || []).map((row) => rowOf(Array.from(row.values || []), Array.from(row.periodHours || []), row, false))
rowsFound = timeRows.length > 0
if (rowsFound) timeRows.push(rowOf([{label: L('Total')}], Array.from(totals.periodHours || []), totals, true))
timeRowsCount = timeRows.length
hoursValue = fmt(totals.hours || 0)
billableValue = fmt(totals.billableHours || 0)
billableShare = totals.hours ? Math.round(Number(totals.billableHours || 0) * 100 / Number(totals.hours)) + '%' : '—'
amountValue = amountsShown ? (totals.mixedCurrency ? L('Several currencies') : money(totals.amount || 0)) : ''
missingRateNote = amountsShown && totals.missingRateCount ? ec.resource.expand('${count} billable entries have no client rate and no amount', '', {count: totals.missingRateCount}) : ''
truncatedNote = out.truncated ? L('More than 50,000 entries matched: the first 50,000 are counted. Narrow the dates or filters.') : ''
rangeText = ec.l10n.format(ec.l10n.parseTimestamp(out.fromDay + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'), 'MMM d, yyyy') + ' – '
    + ec.l10n.format(ec.l10n.parseTimestamp(out.thruDay + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'), 'MMM d, yyyy')
chartTitle = ec.resource.expand('Hours by ${criterion}', '', {criterion: (critTitles[0] || '').toLowerCase()})
const series = Array.from(out.chart?.series || [])
hasChart = rowsFound && series.length > 0
const chart = hasChart ? ec.service.sync().name('ironstone.projects.ReportServices.get#ChartConfig').parameters({id: 'TimeReportChart', type: 'bar',
    labels: Array.from(out.chart.labels || []), series: series.map((one) => ({name: one.name, data: Array.from(one.data || [])})), stacked: true,
    yTitle: L('Hours')}).call() || {} : {}
ec.message.clearErrors()
chartHtml = chart.html || ''
chartTui = chart.tui || {t: 'text', text: ''}
const query = {fromDate: out.fromDay, thruDate: out.thruDay, period: period, criterion1: criterion1 || '', criterion2: criterion2 || '', criterion3: criterion3 || '',
    rootWorkEffortId: rootWorkEffortId || '', workEffortId: workEffortId || '', partyId: partyId || '', workTypeEnumId: workTypeEnumId || '',
    clientPartyId: clientPartyId || '', billable: billable || ''}
printUrl = '/apps/Projects/Reports/Time?renderMode=html-print&' + Object.entries(query).filter(([key, value]) => value).map(([key, value]) => key + '=' + encodeURIComponent(value)).join('&')
